manifest_content:
{
    "name": "@liustack/modlens",
    "version": "3.16.7",
    "description": "Plug-in vision for text-only LLMs, powered by the free Antigravity CLI",
    "type": "module",
    "bin": {
        "modlens": "./dist/main.js"
    },
    "scripts": {
        "dev": "vite build --watch",
        "build": "vite build",
        "typecheck": "tsc --noEmit",
        "test": "vitest run",
        "coverage": "vitest run --coverage",
        "lint": "biome check src scripts dsh",
        "format": "biome check --write src scripts",
        "eval": "node evals/run.mjs",
        "release": "node scripts/release.mjs",
        "prepublishOnly": "pnpm build",
        "docs:list": "node scripts/docs-list.js"
    },
    "files": [
        "dist",
        "docs",
        "skills/modlens/SKILL.md",
        "skills/modlens/scripts",
        "skills/modlens/references",
        "CHANGELOG.md",
        "SECURITY.md",
        "dsh",
        "cordis.patch.yml"
    ],
    "keywords": [
        "cli",
        "vision",
        "ocr",
        "antigravity",
        "agent-skill",
        "claude-code",
        "skill",
        "image-to-text",
        "multimodal",
        "modlens"
    ],
    "author": "Leon Liu",
    "license": "MIT",
    "repository": {
        "type": "git",
        "url": "git+https://github.com/liustack/modlens.git"
    },
    "bugs": {
        "url": "https://github.com/liustack/modlens/issues"
    },
    "homepage": "https://github.com/liustack/modlens#readme",
    "engines": {
        "node": ">=22.19"
    },
    "dependencies": {
        "commander": "^13.1.0",
        "undici": "^8.10.0"
    },
    "devDependencies": {
        "@biomejs/biome": "^2.5.7",
        "@types/node": "^22.19.7",
        "@vitest/coverage-v8": "^3.2.7",
        "typescript": "^5.9.3",
        "vite": "^6.4.1",
        "vitest": "^3.2.7"
    },
    "exports": {
        ".": "./dsh/index.js",
        "./dsh": "./dsh/index.js",
        "./package.json": "./package.json",
        "./client": "./dsh/client.js"
    },
    "dsh": {
        "bundle": {
            "patch": "./cordis.patch.yml"
        },
        "client": {
            "inject": [],
            "platform": "web",
            "immediately": true
        }
    }
}

[workspace]
members = ["crates/*"]
default-members = ["crates/koharu"]
resolver = "3"

[workspace.package]
version = "0.69.0"
edition = "2024"
description = "Manga translation tools"
license = "MIT OR Apache-2.0"
authors = [
    "Mayo Takanashi <mayo@linux.com>",
    "Wangchong Zhou <fffonion@gmail.com>",
]
readme = "README.md"
homepage = "https://koharu.rs"
repository = "https://github.com/mayocream/koharu"
