koharu-runtime = { path = "crates/koharu-runtime" }
koharu-torch = { path = "crates/koharu-torch" }
koharu-torch-sys = { path = "crates/koharu-torch-sys" }
koharu-agent = { path = "crates/koharu-agent" }
koharu-ml = { path = "crates/koharu-ml" }
koharu-pipeline = { path = "crates/koharu-pipeline" }
koharu-translator = { path = "crates/koharu-translator" }
koharu-psd = { path = "crates/koharu-psd" }
koharu-renderer = { path = "crates/koharu-renderer" }
koharu-rasterizer = { path = "crates/koharu-rasterizer", default-features = false }
koharu-desktop = { path = "crates/koharu-desktop" }
